// Graphs: ranking, paths, communities.
// A graph is { n, edges: [[a, b, w?], ...], directed? }.
export function adjacency(g) { const adj = Array.from({ length: g.n }, () => []); for (const [a, b] of g.edges) { adj[a].push(b); if (!g.directed) adj[b].push(a); } return adj; }
export const degree = (g) => adjacency(g).map((l) => l.length);
export function pagerank(g, { d = 0.85, iters = 60 } = {}) { const adj = adjacency(g), n = g.n; let r = new Array(n).fill(1 / n); for (let it = 0; it < iters; it++) { const nx = new Array(n).fill((1 - d) / n); let dangling = 0; for (let i = 0; i < n; i++) { if (!adj[i].length) dangling += r[i]; else for (const j of adj[i]) nx[j] += (d * r[i]) / adj[i].length; } for (let i = 0; i < n; i++) nx[i] += (d * dangling) / n; r = nx; } return r; }
export function hits(g, iters = 40) { const n = g.n; let hub = new Array(n).fill(1), auth = new Array(n).fill(1); for (let it = 0; it < iters; it++) { const a = new Array(n).fill(0), h = new Array(n).fill(0); for (const [x, y] of g.edges) { a[y] += hub[x]; if (!g.directed) a[x] += hub[y]; } const na = Math.hypot(...a) || 1; auth = a.map((v) => v / na); for (const [x, y] of g.edges) { h[x] += auth[y]; if (!g.directed) h[y] += auth[x]; } const nh = Math.hypot(...h) || 1; hub = h.map((v) => v / nh); } return { hub, auth }; }
export function bfs(g, s) { const adj = adjacency(g), dist = new Array(g.n).fill(Infinity), prev = new Array(g.n).fill(-1), q = [s]; dist[s] = 0; for (let h = 0; h < q.length; h++) for (const v of adj[q[h]]) if (dist[v] === Infinity) { dist[v] = dist[q[h]] + 1; prev[v] = q[h]; q.push(v); } return { dist, prev, order: q }; }
export function dijkstra(g, s) { const adj = Array.from({ length: g.n }, () => []); for (const [a, b, w = 1] of g.edges) { adj[a].push([b, w]); if (!g.directed) adj[b].push([a, w]); } const dist = new Array(g.n).fill(Infinity), prev = new Array(g.n).fill(-1), done = new Array(g.n).fill(false); dist[s] = 0; for (let it = 0; it < g.n; it++) { let u = -1; for (let i = 0; i < g.n; i++) if (!done[i] && (u < 0 || dist[i] < dist[u])) u = i; if (u < 0 || dist[u] === Infinity) break; done[u] = true; for (const [v, w] of adj[u]) if (dist[u] + w < dist[v]) { dist[v] = dist[u] + w; prev[v] = u; } } return { dist, prev }; }
export function pathTo(prev, t) { const p = []; for (let v = t; v >= 0; v = prev[v]) p.unshift(v); return p; }
export function closeness(g) { return Array.from({ length: g.n }, (_, i) => { const d = bfs(g, i).dist.filter((x) => x !== Infinity && x > 0); return d.length ? d.length / d.reduce((a, b) => a + b, 0) : 0; }); }
// Brandes: betweenness for nodes and edges
export function betweenness(g) { const n = g.n, adj = adjacency(g), node = new Array(n).fill(0), edge = new Map(), ek = (a, b) => (a < b ? a + '-' + b : b + '-' + a); for (let s = 0; s < n; s++) { const S = [], P = Array.from({ length: n }, () => []), sig = new Array(n).fill(0), dist = new Array(n).fill(-1), q = [s]; sig[s] = 1; dist[s] = 0; for (let h = 0; h < q.length; h++) { const v = q[h]; S.push(v); for (const w of adj[v]) { if (dist[w] < 0) { dist[w] = dist[v] + 1; q.push(w); } if (dist[w] === dist[v] + 1) { sig[w] += sig[v]; P[w].push(v); } } } const del = new Array(n).fill(0); while (S.length) { const w = S.pop(); for (const v of P[w]) { const c = (sig[v] / sig[w]) * (1 + del[w]); edge.set(ek(v, w), (edge.get(ek(v, w)) || 0) + c); del[v] += c; } if (w !== s) node[w] += del[w]; } } if (!g.directed) { for (let i = 0; i < n; i++) node[i] /= 2; for (const [k, v] of edge) edge.set(k, v / 2); } return { node, edge }; }
export function components(g) { const adj = adjacency(g), comp = new Array(g.n).fill(-1); let c = 0; for (let i = 0; i < g.n; i++) { if (comp[i] >= 0) continue; const q = [i]; comp[i] = c; for (let h = 0; h < q.length; h++) for (const v of adj[q[h]]) if (comp[v] < 0) { comp[v] = c; q.push(v); } c++; } return { comp, count: c }; }
export function modularity(g, comm) { const m = g.edges.length; if (!m) return 0; const deg = degree(g); let q = 0; const inside = new Map(), tot = new Map(); for (const [a, b] of g.edges) if (comm[a] === comm[b]) inside.set(comm[a], (inside.get(comm[a]) || 0) + 1); deg.forEach((d, i) => tot.set(comm[i], (tot.get(comm[i]) || 0) + d)); for (const [c, t] of tot) q += (inside.get(c) || 0) / m - (t / (2 * m)) ** 2; return q; }
// Girvan and Newman: remove the edge with the highest betweenness
export function girvanNewmanStep(g) { const { edge } = betweenness(g); let best = null, bv = -1; for (const [k, v] of edge) if (v > bv) { bv = v; best = k; } if (!best) return g; const [a, b] = best.split('-').map(Number); return { ...g, edges: g.edges.filter(([x, y]) => !((x === a && y === b) || (x === b && y === a))), removed: [a, b] }; }
export function labelPropagation(g, rng, iters = 20) { const adj = adjacency(g); let lab = Array.from({ length: g.n }, (_, i) => i); for (let it = 0; it < iters; it++) { let changed = false; for (const i of rng.shuffle(lab.map((_, j) => j))) { const c = new Map(); for (const j of adj[i]) c.set(lab[j], (c.get(lab[j]) || 0) + 1); let best = lab[i], bc = 0; for (const [l, n] of c) if (n > bc || (n === bc && l < best)) { bc = n; best = l; } if (best !== lab[i]) { lab[i] = best; changed = true; } } if (!changed) break; } const ids = [...new Set(lab)]; return lab.map((l) => ids.indexOf(l)); }
export function clusteringCoef(g) { const adj = adjacency(g).map((l) => new Set(l)); let tot = 0, cnt = 0; for (let i = 0; i < g.n; i++) { const nb = [...adj[i]]; if (nb.length < 2) continue; let tri = 0; for (let a = 0; a < nb.length; a++) for (let b = a + 1; b < nb.length; b++) if (adj[nb[a]].has(nb[b])) tri++; tot += tri / ((nb.length * (nb.length - 1)) / 2); cnt++; } return cnt ? tot / cnt : 0; }
export const density = (g) => (g.n > 1 ? (2 * g.edges.length) / (g.n * (g.n - 1)) : 0);
// one step of a spring layout
export function springStep(pos, g, { k = 1.2, step = 0.05 } = {}) { const n = pos.length, f = pos.map(() => [0, 0]); for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) { let dx = pos[i][0] - pos[j][0], dy = pos[i][1] - pos[j][1]; const d = Math.hypot(dx, dy) || 0.01, r = (k * k) / d; dx /= d; dy /= d; f[i][0] += dx * r; f[i][1] += dy * r; f[j][0] -= dx * r; f[j][1] -= dy * r; } for (const [a, b] of g.edges) { let dx = pos[a][0] - pos[b][0], dy = pos[a][1] - pos[b][1]; const d = Math.hypot(dx, dy) || 0.01, at = (d * d) / k; dx /= d; dy /= d; f[a][0] -= dx * at; f[a][1] -= dy * at; f[b][0] += dx * at; f[b][1] += dy * at; } let moved = 0; const out = pos.map((p, i) => { const m = Math.hypot(f[i][0], f[i][1]) || 1, s = Math.min(m, 1) * step; moved += s; return [p[0] + (f[i][0] / m) * s - p[0] * 0.01, p[1] + (f[i][1] / m) * s - p[1] * 0.01]; }); return { pos: out, moved }; }
export function randomGraph(n, p, rng) { const edges = []; for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) if (rng.chance(p)) edges.push([i, j]); return { n, edges }; }
export function preferential(n, m, rng) { const edges = [], ends = []; for (let i = 0; i < n; i++) { const t = new Set(); while (t.size < Math.min(m, i)) t.add(ends.length ? ends[rng.int(0, ends.length - 1)] : rng.int(0, i - 1)); for (const j of t) { edges.push([i, j]); ends.push(i, j); } if (!i) ends.push(0); } return { n, edges }; }
// a graph with planted groups: p inside, q across
export function planted(sizes, pin, pout, rng) { const comm = []; sizes.forEach((s, c) => { for (let i = 0; i < s; i++) comm.push(c); }); const n = comm.length, edges = []; for (let i = 0; i < n; i++) for (let j = i + 1; j < n; j++) if (rng.chance(comm[i] === comm[j] ? pin : pout)) edges.push([i, j]); return { n, edges, comm }; }
